const axios = require("axios")
const cheerio = require("cheerio")

const headers = {
    "user-agent":
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36"
}

// 🔹 GOOGLE (puede fallar)
async function fromGoogle(query) {
    try {
        const { data } = await axios.get(
            `https://www.google.com/search?q=${encodeURIComponent(query)}&tbm=isch`,
            { headers }
        )

        const regex = /"ou":"(.*?)"/g
        let match
        const results = []

        while ((match = regex.exec(data)) !== null) {
            results.push(match[1])
        }

        return [...new Set(results)]
    } catch {
        return []
    }
}

// 🔹 BING (estable)
async function fromBing(query) {
    const { data } = await axios.get(
        `https://www.bing.com/images/search?q=${encodeURIComponent(query)}`,
        { headers }
    )

    const $ = cheerio.load(data)
    const results = []

    $("a.iusc").each((_, el) => {
        const m = $(el).attr("m")
        if (!m) return

        try {
            const json = JSON.parse(m)
            if (json.murl) results.push(json.murl)
        } catch {}
    })

    return results
}

// 🔥 MAIN
async function gimage(query, limit = 10) {
    let results = await fromGoogle(query)

    // fallback automático
    if (!results.length) {
        console.log("⚠️ Google falló, usando Bing...")
        results = await fromBing(query)
    }

    // limpiar
    results = [...new Set(results)]
        .filter(v => /\.(jpg|jpeg|png|webp)$/i.test(v))

    return results.slice(0, limit)
}

module.exports = { gimage }